# Quiz helpers keep game state on the Application instance.
def quiz_render(app):
    # Stop accepting answers after the last question.
    buttons = [app.Answer1, app.Answer2, app.Answer3, app.Answer4]
    if app.quiz_index >= len(app.quiz_questions):
        app.QuestionLabel.configure(text="Quiz complete!")
        for button in buttons:
            button.configure(state="disabled")
    else:
        question, options, correct = app.quiz_questions[app.quiz_index]
        app.QuestionLabel.configure(text=question)
        for button, option in zip(buttons, options):
            button.configure(text=option, state="normal")
    app.ScoreLabel.configure(text=f"Score: {app.quiz_score} / {len(app.quiz_questions)}")


def quiz_reset(app):
    # Reset both counters before displaying the first question.
    app.quiz_index = 0
    app.quiz_score = 0
    quiz_render(app)


def quiz_answer(app, answer):
    # The guard prevents clicks from changing a finished quiz.
    if app.quiz_index >= len(app.quiz_questions):
        return
    if answer == app.quiz_questions[app.quiz_index][2]:
        app.quiz_score += 1
    app.quiz_index += 1
    quiz_render(app)
